diff --git a/js/common/tokenUsageComment.js b/js/common/tokenUsageComment.js
index dedb970a..ccfd1d13 100644
--- a/js/common/tokenUsageComment.js
+++ b/js/common/tokenUsageComment.js
@@ -23,6 +23,8 @@ var MANIFEST_NAME = 'token_usage_files.json';
 // ./trackers.js"); load-time requires resolve file-relative and dmtools
 // compile discovers them for the pack closure.
 var trackersModule = require('./trackers.js');
+var configLoader = null;
+try { configLoader = require('../configLoader.js'); } catch (e) { /* unit tests inject their own */ }

 function readTextFile(filePath) {
     if (!filePath) {
@@ -164,6 +166,25 @@ function customParamsOf(params) {
         (params && params.customParams) || {};
 }

+/**
+ * The project config used to pick the tracker provider: the caller's options.config when given;
+ * otherwise, only when the provider is not already pinned by customParams.trackerProvider, the
+ * project config (config.tracker.provider) loaded best-effort, so a run that sets the provider only
+ * there does not fall through to the Jira default (agents#942). Fail-open: null on any problem.
+ * @param {Object} options postTokenUsageComments options
+ * @returns {Object|null}
+ */
+function resolveConfig(options) {
+    if (options.config) return options.config;
+    var cp = options.customParams || {};
+    if (cp.trackerProvider || !configLoader || typeof configLoader.loadProjectConfig !== 'function') return null;
+    try {
+        return configLoader.loadProjectConfig({ customParams: cp }) || null;
+    } catch (e) {
+        return null;
+    }
+}
+
 /**
  * Post token usage comments for the given ticket.
  *
@@ -200,7 +221,7 @@ function postTokenUsageComments(ticketKey, options) {
         }

         try {
-            if (!tracker) tracker = trackersModule.createTracker(options.config || null, options.customParams || {});
+            if (!tracker) tracker = trackersModule.createTracker(resolveConfig(options), options.customParams || {});
             var comment = formatUsageComment(filePath, data, initiator,
                 typeof tracker.provider === 'function' ? tracker.provider() : null);
             tracker.postComment(ticketKey, comment);
diff --git a/js/unit-tests/test_tokenUsageComment.js b/js/unit-tests/test_tokenUsageComment.js
index 86a6d707..66922898 100644
--- a/js/unit-tests/test_tokenUsageComment.js
+++ b/js/unit-tests/test_tokenUsageComment.js
@@ -314,3 +314,55 @@ suite('tokenUsageComment — Azure DevOps rendering (agents#877, #878)', functio
     });
 });

+
+suite('tokenUsageComment — provider from the project config (agents#942)', function() {
+    function load(loader, mocks) {
+        return loadModule('js/common/tokenUsageComment.js', makeRequire({
+            './trackers.js': loadModule('js/common/trackers.js', makeRequire({
+                '../config.js': configModule,
+                './ticketKeyShapes.js': loadModule('js/common/ticketKeyShapes.js')
+            }), mocks),
+            '../configLoader.js': loader
+        }), mocks);
+    }
+    function mocks(extra) {
+        var m = {
+            file_read: function(opts) {
+                if (opts.path === 'outputs/token_usage_files.json') return JSON.stringify(['outputs/a_usage.json']);
+                if (opts.path === 'outputs/a_usage.json') return JSON.stringify({ provider: 'copilot', total_tokens: 5 });
+                return null;
+            }
+        };
+        Object.keys(extra).forEach(function(k) { m[k] = extra[k]; });
+        return m;
+    }
+
+    test('config.tracker.provider=ado with no trackerProvider: posts through ADO, not jira_post_comment', function() {
+        var ado = [], jira = [];
+        var mod = load({ loadProjectConfig: function() { return { tracker: { provider: 'ado' } }; } },
+            mocks({ ado_add_work_item_comment: function(a) { ado.push(a); }, jira_post_comment: function(a) { jira.push(a); } }));
+        var r = mod.postTokenUsageComments('2010283', { customParams: {} });
+        assert.equal(r.posted, 1, JSON.stringify(r));
+        assert.equal(ado.length, 1);
+        assert.equal(jira.length, 0);
+    });
+
+    test('customParams.trackerProvider wins and the project config is not consulted', function() {
+        var loaded = 0, ado = [];
+        var mod = load({ loadProjectConfig: function() { loaded++; return { tracker: { provider: 'jira' } }; } },
+            mocks({ ado_add_work_item_comment: function(a) { ado.push(a); } }));
+        var r = mod.postTokenUsageComments('1', { customParams: { trackerProvider: 'ado' } });
+        assert.equal(r.posted, 1, JSON.stringify(r));
+        assert.equal(loaded, 0);
+        assert.equal(ado.length, 1);
+    });
+
+    test('a throwing config loader falls back to the Jira default (fail-open, as before)', function() {
+        var jira = [];
+        var mod = load({ loadProjectConfig: function() { throw new Error('boom'); } },
+            mocks({ jira_post_comment: function(a) { jira.push(a); } }));
+        var r = mod.postTokenUsageComments('PROJ-1', { customParams: {} });
+        assert.equal(r.posted, 1, JSON.stringify(r));
+        assert.equal(jira.length, 1);
+    });
+});

{
  "key": "pr-958",
  "fields": {
    "summary": "fix(tokenUsage): usage comment honours config.tracker.provider (ADO) — gh-942",
    "description": "Fixes #942. When no tracker/config/trackerProvider is passed, postTokenUsageComments now loads the project config best-effort so config.tracker.provider=ado is honoured. Explicit tracker/config/customParams.trackerProvider keep priority (config not even loaded); loader failure falls back to the old Jira default. 3 new tests."
  }
}

