 * @returns {object} Result summary { posted: number, files: string[], errors: string[] }.
 */
function postTokenUsageComments(ticketKey, options) {
    options = options || {};
    var outputsDir = options.outputsDir || OUTPUTS_DIR;
    var initiator = options.initiator || '';
