    var n = source.length;
    var depths = new Array(n);
    var commented = new Array(n);
    var stack = [];
    var pendingFunction = 0;
    var fnCount = 0;
    var i = 0;
    var inLine = false;
    var inBlock = false;
    var inStr = null;
    var inRegex = false;
